import { State } from "../core/color.js";
import { toDegreesSigned, map, rr } from "../core/utils.js";
import { Polygon } from "../core/polygon.js";
import { Plot } from "../core/plot.js";
import { BrushState, BrushSetState, pick, stroke, strokeWeight, line } from "../stroke/stroke.js";

// =============================================================================
// Module: Classic Hatch
// =============================================================================

// ---------------------------------------------------------------------------
// Hatch State
// ---------------------------------------------------------------------------

State.hatch = {
  isActive: false,
  dist: 5,
  angle: 45,
  options: {},
  hBrush: false,
};

/**
 * Returns a shallow snapshot of the current hatch modifier state.
 *
 * @returns {{isActive:boolean, dist:number, angle:number, options:Object, hBrush:Object|false}}
 */
export function HatchState() {
  return { ...State.hatch };
}

/**
 * Restores hatch modifier state from a previously captured snapshot.
 *
 * @param {{isActive:boolean, dist:number, angle:number, options:Object, hBrush:Object|false}} state
 */
export function HatchSetState(state) {
  State.hatch = { ...state };
}

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

/**
 * Activates classic scanline hatching for subsequent shapes.
 *
 * @param {number} [dist=5] Distance between scanlines.
 * @param {number} [angle=45] Hatch angle in the current runtime angle units.
 * @param {{rand?: number|false, continuous?: boolean, gradient?: number|false}} [options]
 */
export function hatch(
  dist = 5,
  angle = 45,
  options = { rand: false, continuous: false, gradient: false }
) {
  if (!Number.isFinite(dist) || dist <= 0) {
    throw new Error("hatch() distance must be finite and greater than zero.");
  }
  if (!Number.isFinite(angle)) {
    throw new Error("hatch() angle must be finite.");
  }
  let s = State.hatch;
  s.isActive = true;
  s.dist = dist;
  s.angle = toDegreesSigned(angle);
  s.options = options;
}

/**
 * Overrides the brush, color, and weight used specifically for hatch strokes.
 *
 * @param {string} brush
 * @param {string|object} [color="black"]
 * @param {number} [weight=1]
 */
export function hatchStyle(brush, color = "black", weight = 1) {
  State.hatch.hBrush = { brush, color, weight };
}

/**
 * Deactivates hatching and clears any hatch-specific brush override.
 */
export function noHatch() {
  State.hatch.isActive = false;
  State.hatch.hBrush = false;
}

// ---------------------------------------------------------------------------
// Scanline Generation
// ---------------------------------------------------------------------------

/**
 * Computes hatch segments for one polygon by rotating it into scanline space,
 * intersecting horizontal scanlines against its edges, and rotating the
 * resulting segments back into canvas space.
 *
 * @param {Polygon} polygon
 * @param {number} angle Hatch angle in degrees.
 * @param {number} dist Base scanline spacing.
 * @param {number} gradient Multiplicative spacing growth per scanline.
 * @returns {{scanY:number, x1:number, y1:number, x2:number, y2:number}[]}
 */
// Reusable buffers for scanlineHatch to avoid per-call allocations
let _sRotX = new Float64Array(256);
let _sRotY = new Float64Array(256);
let _eX1 = new Float64Array(512);
let _eY1 = new Float64Array(512);
let _eX2 = new Float64Array(512);
let _eY2 = new Float64Array(512);
let _eDir = new Int8Array(512);
let _eMinY = new Float64Array(512);
let _eOrder = new Int32Array(512);
let _eActive = new Int32Array(512);

function scanlineHatch(polygons, angle, dist, gradient, rule = "evenodd") {
  if (!Array.isArray(polygons)) polygons = [polygons];

  const rad = (angle * Math.PI) / 180;
  const cosA = Math.cos(rad),
    sinA = Math.sin(rad);
  // cos(-rad) = cosA, sin(-rad) = -sinA — no extra trig needed
  const sinB = -sinA;

  // Polygons, or plain arrays of [x, y] points.
  const contours = polygons.map((polygon) => polygon.a ?? polygon);
  let totalVerts = 0;
  for (const verts of contours) totalVerts += verts.length;
  if (totalVerts === 0) return [];

  // Grow reusable vertex buffers if needed
  if (_sRotX.length < totalVerts) {
    _sRotX = new Float64Array(totalVerts * 2);
    _sRotY = new Float64Array(totalVerts * 2);
  }

  // Rotate all contour vertices into scan space; track the combined Y extent
  let minY = Infinity,
    maxY = -Infinity;
  let eLen = 0;
  let vLen = 0;
  if (_eX1.length < totalVerts) {
    _eX1 = new Float64Array(totalVerts * 2);
    _eY1 = new Float64Array(totalVerts * 2);
    _eX2 = new Float64Array(totalVerts * 2);
    _eY2 = new Float64Array(totalVerts * 2);
    _eDir = new Int8Array(totalVerts * 2);
    _eMinY = new Float64Array(totalVerts * 2);
    _eOrder = new Int32Array(totalVerts * 2);
    _eActive = new Int32Array(totalVerts * 2);
  }

  // Build one flat edge list across all contours so crossings pair globally.
  for (const verts of contours) {
    const n = verts.length;
    const base = vLen;

    for (let i = 0; i < n; i++) {
      const x = verts[i][0],
        y = verts[i][1];
      _sRotX[vLen] = x * cosA - y * sinA;
      _sRotY[vLen] = x * sinA + y * cosA;
      if (_sRotY[vLen] < minY) minY = _sRotY[vLen];
      if (_sRotY[vLen] > maxY) maxY = _sRotY[vLen];
      vLen++;
    }

    for (let i = 0; i < n; i++) {
      const j = i + 1 < n ? i + 1 : 0;
      const ai = base + i;
      const bj = base + j;
      const ay = _sRotY[ai], by = _sRotY[bj];
      if (ay !== by) {
        _eX1[eLen] = _sRotX[ai];
        _eY1[eLen] = ay;
        _eX2[eLen] = _sRotX[bj];
        _eY2[eLen] = by;
        _eDir[eLen] = ay < by ? 1 : -1;
        _eMinY[eLen] = ay < by ? ay : by;
        _eOrder[eLen] = eLen;
        eLen++;
      }
    }
  }

  // Edges join the active list once the scanline reaches their lowest y and
  // leave it once the scanline passes their highest, so each scanline only
  // tests the edges that can cross it.
  const order = _eOrder.subarray(0, eLen).sort((a, b) => _eMinY[a] - _eMinY[b]);
  let nextEdge = 0, activeLen = 0;

  // Scan, find crossings, rotate back
  const segments = [];
  const crossings = [];
  const inside = rule === "nonzero" ? (wind) => wind !== 0 : (wind) => (wind & 1) !== 0;
  let Y = minY + dist * 0.5,
    step = dist;
  const useGradient = gradient !== 1;
  let scanCount = 0;
  while (Y < maxY) {
    if (++scanCount > 1_000_000 || !(Y + step > Y)) {
      throw new Error("Hatch spacing is too small to advance safely.");
    }
    while (nextEdge < eLen && _eMinY[order[nextEdge]] <= Y) _eActive[activeLen++] = order[nextEdge++];
    crossings.length = 0;
    let kept = 0;
    for (let k = 0; k < activeLen; k++) {
      const i = _eActive[k];
      const y1 = _eY1[i], y2 = _eY2[i];
      // Active edges start at or below Y; an edge crosses while its top is above Y.
      if ((y1 > y2 ? y1 : y2) <= Y) continue;
      _eActive[kept++] = i;
      crossings.push({ x: _eX1[i] + ((Y - y1) / (y2 - y1)) * (_eX2[i] - _eX1[i]), dir: _eDir[i], i });
    }
    activeLen = kept;
    // Ties keep edge order, as the full scan did.
    crossings.sort((a, b) => a.x - b.x || a.i - b.i);
    // Walk the crossings with a winding counter; a segment runs while the
    // fill rule counts the winding as inside.
    let wind = 0, start = 0;
    for (const c of crossings) {
      const wasInside = inside(wind);
      wind += c.dir;
      if (!wasInside && inside(wind)) start = c.x;
      else if (wasInside && !inside(wind)) {
        segments.push({
          scanY: Y,
          x1: start * cosA + Y * sinA,
          y1: -start * sinA + Y * cosA,
          x2: c.x * cosA + Y * sinA,
          y2: -c.x * sinA + Y * cosA,
        });
      }
    }
    Y += step;
    if (useGradient) step *= gradient;
  }
  return segments;
}

/**
 * Collects and orders hatch segments for one polygon or a polygon list.
 *
 * Segments are sorted in scanline traversal order so downstream rendering can
 * optionally connect them into a continuous serpentine path.
 *
 * @param {Polygon|Polygon[]} polygons
 * @param {number} dist
 * @param {number} angle
 * @param {number} gradient
 * @returns {{scanY:number, x1:number, y1:number, x2:number, y2:number}[]}
 */
function getHatchSegments(polygons, dist, angle, gradient, rule) {
  const segs = scanlineHatch(polygons, angle, dist, gradient, rule);
  segs.sort((a, b) => (a.scanY === b.scanY ? a.x1 - b.x1 : a.scanY - b.scanY));
  return segs;
}

// ---------------------------------------------------------------------------
// Hatch Configuration
// ---------------------------------------------------------------------------

/**
 * Runs hatch drawing with the temporary hatch-specific brush style if one is active,
 * then restores the outer stroke state.
 *
 * @param {() => void} drawFn
 */
function withHatchStyle(drawFn) {
  const save = BrushState();
  try {
    const style = State.hatch.hBrush;
    if (style) {
      pick(style.brush);
      stroke(style.color);
    }
    drawFn();
  } finally {
    BrushSetState(save);
  }
}

/**
 * Resolves the active hatch parameters and precomputes the ordered scanline segments.
 *
 * @param {Polygon|Polygon[]} polygons
 * @returns {{dist:number, options:Object, segs:Object[]}}
 */
function getActiveHatchConfig(polygons, rule) {
  const dist = State.hatch.dist;
  const angle = ((State.hatch.angle % 180) + 180) % 180;
  const options = State.hatch.options;
  const gradient = options.gradient ? map(options.gradient, 0, 1, 1, 1.1, true) : 1;
  const segs = getHatchSegments(polygons, dist, angle, gradient, rule);
  return { dist, options, segs };
}

// ---------------------------------------------------------------------------
// Hatch Lines
// ---------------------------------------------------------------------------

/**
 * Expands ordered hatch segments into the actual line list that will be drawn.
 *
 * This includes endpoint jitter when `rand` is active and inserts the serpentine
 * connector lines when `continuous` is enabled.
 *
 * @param {Polygon|Polygon[]} polygons
 * @returns {{x1:number, y1:number, x2:number, y2:number, scanY:number, isConnector:boolean}[]}
 */
export function getHatchLines(polygons, rule = "evenodd") {
  const { dist, options, segs } = getActiveHatchConfig(polygons, rule);
  const r = options.rand || 0;
  const lines = [];

  for (let j = 0; j < segs.length; j++) {
    const s = segs[j];
    let x1 = s.x1, y1 = s.y1, x2 = s.x2, y2 = s.y2;
    if (r) {
      x1 += 2 * r * dist * rr(-1, 1);
      y1 += 2 * r * dist * rr(-1, 1);
      x2 += 2 * r * dist * rr(-1, 1);
      y2 += 2 * r * dist * rr(-1, 1);
    }
    const reverse = options.continuous && j % 2 === 1;
    const line = reverse
      ? { x1: x2, y1: y2, x2: x1, y2: y1, scanY: s.scanY, isConnector: false }
      : { x1, y1, x2, y2, scanY: s.scanY, isConnector: false };
    lines.push(line);
    if (j > 0 && options.continuous) {
      const prev = lines[lines.length - 2];
      lines.push({
        x1: prev.x2,
        y1: prev.y2,
        x2: line.x1,
        y2: line.y1,
        scanY: s.scanY,
        isConnector: true,
      });
    }
  }

  return lines;
}

// ---------------------------------------------------------------------------
// Hatch Rendering
// ---------------------------------------------------------------------------

/**
 * Iterates the generated hatch lines and delegates the actual rendering of each
 * segment to the provided callback.
 *
 * @param {Polygon|Polygon[]} polygons
 * @param {(x1:number, y1:number, x2:number, y2:number, index:number, segs:Object[]) => void} drawSegment
 */
function renderHatchSegments(polygons, drawSegment, rule) {
  const segs = getHatchLines(polygons, rule);
  if (segs.length === 0) return;
  withHatchStyle(() => {
    for (let j = 0; j < segs.length; j++) {
      const s = segs[j];
      drawSegment(s.x1, s.y1, s.x2, s.y2, j, segs);
    }
  });
}

/**
 * Validates a fill rule option: "evenodd" (default) or "nonzero".
 *
 * @param {{rule?: string}} [options]
 * @returns {"evenodd"|"nonzero"}
 */
export function fillRule(options) {
  const rule = options?.rule ?? "evenodd";
  if (rule !== "evenodd" && rule !== "nonzero") {
    throw new Error(`Unknown fill rule "${rule}"; use "evenodd" or "nonzero".`);
  }
  return rule;
}

/**
 * Draws classic hatch lines over one polygon or an array of polygons.
 *
 * @param {Polygon|Array<Polygon|number[][]>} polygons - Polygons, or arrays
 *   of [x, y] points.
 * @param {{rule?: "evenodd"|"nonzero"}} [options] How overlapping contours
 *   combine: "evenodd" (default) leaves overlaps unhatched, "nonzero" hatches them.
 */
export function createHatch(polygons, options) {
  const rule = fillRule(options);
  renderHatchSegments(polygons, (x1, y1, x2, y2) => {
    // The hatch brush and colour are set once for all lines; only the weight varies.
    if (State.hatch.hBrush) strokeWeight(State.hatch.hBrush.weight * rr(0.9, 1.1));
    line(x1, y1, x2, y2);
  }, rule);
}

// ---------------------------------------------------------------------------
// Prototype Extensions
// ---------------------------------------------------------------------------

/**
 * Applies the currently active hatch modifier to a polygon, or temporarily
 * overrides hatch parameters for this call only.
 *
 * @param {number|false} [_dist=false]
 * @param {number} [_angle]
 * @param {{rand?: number|false, continuous?: boolean, gradient?: number|false}} [_options]
 */
Polygon.prototype.hatch = function (_dist = false, _angle, _options) {
  let state = HatchState();
  try {
    if (_dist !== false) hatch(_dist, _angle, _options);
    if (State.hatch.isActive) createHatch(this);
  } finally {
    HatchSetState(state);
  }
  return this;
};

/**
 * Converts the plot to a polygon and applies the currently active hatch modifier.
 *
 * @param {number} x
 * @param {number} y
 * @param {number} scale
 */
Plot.prototype.hatch = function (x, y, scale) {
  if (HatchState().isActive) {
    if (this.origin) (x = this.origin[0]), (y = this.origin[1]), (scale = 1);
    this.pol = this.genPol(x, y, scale, 0.3);
    this.pol.hatch();
  }
};
